mapper.select:
SELECT USER_ID, EMAIL, NICKNAME, ROLE, STATUS, OAUTH_PROVIDER, LAST_LOGIN_AT, CREATED_AT
FROM USERS

    DELETED_AT IS NULL

        AND (EMAIL LIKE CONCAT('%', #{keyword}, '%')
             OR NICKNAME LIKE CONCAT('%', #{keyword}, '%'))


        AND STATUS = #{status}


        AND ROLE = #{role}


ORDER BY USER_ID DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM USERS

    DELETED_AT IS NULL

        AND (EMAIL LIKE CONCAT('%', #{keyword}, '%')
             OR NICKNAME LIKE CONCAT('%', #{keyword}, '%'))


        AND STATUS = #{status}


        AND ROLE = #{role}

SELECT L.LISTING_ID, L.TITLE, L.DEAL_TYPE, L.STATUS, L.HOST_USER_ID AS OWNER_USER_ID, U.NICKNAME AS OWNER_NICKNAME, L.DEPOSIT AS PRICE_DEPOSIT, L.MONTHLY_RENT AS PRICE_MONTHLY, (SELECT COUNT(*) FROM LISTING_REPORTS R WHERE R.LISTING_ID = L.LISTING_ID) AS REPORT_COUNT, L.CREATED_AT FROM LISTINGS L JOIN USERS U ON U.USER_ID = L.HOST_USER_ID
AND L.STATUS = #{status}
AND L.TITLE LIKE CONCAT('%', #{keyword}, '%')
ORDER BY L.LISTING_ID DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM LISTINGS L


        AND L.STATUS = #{status}


        AND L.TITLE LIKE CONCAT('%', #{keyword}, '%')

SELECT R.REPORT_ID, R.LISTING_ID, L.TITLE AS LISTING_TITLE, R.REPORTER_USER_ID, U.NICKNAME AS REPORTER_NICKNAME, R.REASON, R.STATUS, R.CREATED_AT FROM LISTING_REPORTS R JOIN LISTINGS L ON L.LISTING_ID = R.LISTING_ID JOIN USERS U ON U.USER_ID = R.REPORTER_USER_ID
AND R.STATUS = #{status}
ORDER BY R.CREATED_AT DESC LIMIT #{size} OFFSET #{offset}

SELECT O.ORDER_ID, O.ORDER_CODE, O.USER_ID, U.NICKNAME AS USER_NICKNAME, U.EMAIL AS USER_EMAIL, O.TOTAL, O.STATUS, P.METHOD AS PAYMENT_METHOD, P.STATUS AS PAYMENT_STATUS, (SELECT R.STATUS FROM REFUNDS R WHERE R.ORDER_ID = O.ORDER_ID ORDER BY R.REFUND_ID DESC LIMIT 1) AS REFUND_STATUS, O.CREATED_AT FROM ORDERS O JOIN USERS U ON U.USER_ID = O.USER_ID LEFT JOIN PAYMENTS P ON P.ORDER_ID = O.ORDER_ID
O.STATUS = #{status}
AND (O.ORDER_CODE LIKE CONCAT('%', #{keyword}, '%') OR U.NICKNAME LIKE CONCAT('%', #{keyword}, '%') OR U.EMAIL LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY O.CREATED_AT DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM ORDERS O JOIN USERS U ON U.USER_ID = O.USER_ID
O.STATUS = #{status}
AND (O.ORDER_CODE LIKE CONCAT('%', #{keyword}, '%') OR U.NICKNAME LIKE CONCAT('%', #{keyword}, '%') OR U.EMAIL LIKE CONCAT('%', #{keyword}, '%'))
